.darma-loader-darma-b15-loom-weave { --accent: var(--loader-color, #0d9488); --accent-2: var(--loader-secondary-color, #f59e0b); width: var(--loader-size, 124px); height: calc(var(--loader-size, 124px) * .74); position: relative; overflow: hidden; border-radius: 6px; }
.darma-loader-darma-b15-loom-weave .darma-loader-darma-b15-loom-weave__warp { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, color-mix(in srgb, var(--accent) 45%, transparent) 0 6%, transparent 0 14%); }
.darma-loader-darma-b15-loom-weave span { position: absolute; left: 4%; width: 92%; height: 9%; border-radius: 3px; background: var(--accent); transform-origin: left center; transform: scaleX(0); animation: darma-loader-darma-b15-loom-weave-loom-pass calc(var(--loader-speed, 1s) * 2.8) ease-in-out infinite; }
.darma-loader-darma-b15-loom-weave span:nth-of-type(1) { bottom: 7%; }
.darma-loader-darma-b15-loom-weave span:nth-of-type(2) { bottom: 26%; animation-delay: calc(var(--loader-speed, 1s) * .32); }
.darma-loader-darma-b15-loom-weave span:nth-of-type(3) { bottom: 45%; animation-delay: calc(var(--loader-speed, 1s) * .64); }
.darma-loader-darma-b15-loom-weave span:nth-of-type(4) { bottom: 64%; animation-delay: calc(var(--loader-speed, 1s) * .96); }
.darma-loader-darma-b15-loom-weave .darma-loader-darma-b15-loom-weave__shuttle { position: absolute; top: 5%; left: 0; width: 17%; height: 11%; border-radius: 40% 6% 6% 40%; background: linear-gradient(90deg, var(--accent-2), color-mix(in srgb, #000 18%, var(--accent-2))); animation: darma-loader-darma-b15-loom-weave-loom-slide calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite alternate; }
@keyframes darma-loader-darma-b15-loom-weave-loom-pass { 0% { transform: scaleX(0); opacity: .15; } 28%, 68% { transform: scaleX(1); opacity: 1; } 100% { transform: scaleX(0); opacity: .15; } }
@keyframes darma-loader-darma-b15-loom-weave-loom-slide { from { left: 0; } to { left: 83%; } }

